    EnergyInventorySlot energySlot;

    public TileEntityDigitalMiner(BlockPos pos, BlockState state) {
        mainSlots = new ArrayList<>();
        super(MekanismBlocks.DIGITAL_MINER, pos, state);
        directMainHandler = () -> mainSlots;
